.findBar {
  background: #bbb;
  opacity: 0.9;
  padding: 5px 10px;
  position: absolute;
  top: 0;
  right: 0;
}
.findBar .findButton {
  margin: 0 2px;
}
.findBar .findButton.hideButton:not([disabled]):hover {
  background: #A0A2A4;
}
.findBar .searchStringContainer {
  position: relative;
}
.findBar .searchStringContainer input {
  width: 200px;
  margin-right: 5px;
  padding-right: 28px;
}
.findBar .searchStringContainer span {
  color: black;
  font-size: 10px;
  margin-right: 8px;
  position: absolute;
  right: 0;
  top: 5px;
}
.findBar .caseSensitivityContainer {
  color: white;
  font-size: 12px;
  margin-top: 6px;
}
.findBar .caseSensitivityContainer input {
  margin-right: 6px;
}
