.updateBar {
  background-color: #fff;
  border-bottom: 1px solid #888;
  padding: 5px 20px;
}
.updateBar > div {
  display: flex;
}
.updateBar .updateHello {
  color: #EB431C;
  font-size: 18px;
  margin: auto 0;
}
.updateBar .updateMessage {
  color: #000;
  font-size: 15px;
  padding-left: 10px;
  margin: auto 0;
}
.updateBar .updateSecondaryButton {
  background-color: #eee;
}
.updateBar .updateButton {
  padding: 0px 25px;
  float: right;
  font-size: 14px;
  width: auto;
  margin: auto 5px;
}
.updateBar .updateRequiresRelaunch {
  color: #888;
  font-size: 14px;
  margin: auto 0 auto 10px;
}
.updateBar .updateSpacer {
  flex-grow: 1;
}
.updateBar .updateNowButton {
  background-color: #EB431C;
  color: #fff;
  margin-right: 0px;
}
