.tabs {
  background: #CCCCCC;
  box-sizing: border-box;
  display: flex;
  flex: 1;
  padding: 0 4px 0 6px;
  height: 26px;
  position: relative;
  white-space: nowrap;
  z-index: 310;
}
.tabContainer {
  display: flex;
  flex: 1;
  z-index: 2;
}
.tabContainer .browserButton {
  height: 26px;
  line-height: 26px;
}
.tab {
  border-radius: 10px;
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
  border-width: 1px 1px 0;
  box-sizing: border-box;
  color: #3B3B3B;
  display: flex;
  height: 20px;
  margin: 0;
  position: relative;
  transition: transform 200ms ease;
  left: 0;
  opacity: 1;
  padding: 0;
  width: 100%;
  -moz-window-dragging: no-drag;
}
.tab:not(.isPinned) {
  background: linear-gradient(to bottom, #BEBFC2, #AFB0B4);
}
.tab .tabTitle {
  -webkit-user-select: none;
  box-sizing: border-box;
  display: inline-block;
  font-size: 11px;
  margin: auto 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
  width: calc(100% - 26px);
}
.tab .tabIcon {
  background-position: center;
  background-repeat: no-repeat;
  display: inline-block;
  font-size: 12px;
  margin: auto 9px;
  position: relative;
  vertical-align: middle;
}
.tab .privateIcon {
  background-position: center;
  background-repeat: no-repeat;
  display: inline-block;
  font-size: 14px;
  margin: auto 0px auto 9px;
  position: relative;
  vertical-align: middle;
}
.tab .audioPlaybackActive {
  margin: auto 4px auto 0;
  color: #0076FF;
}
.tab .thumbnail {
  display: none;
  position: absolute;
  top: 32px;
  left: 0;
  border: 1px solid #000;
  padding: 10px;
  background: #fff;
  pointer-events: none;
  z-index: 312;
}
.tab.active {
  background: white;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  height: 26px;
}
.tab.private {
  background: #392e54;
  color: #fff;
}
.tab.private:not(.active) {
  background: #9c8dc1;
}
.tab:hover .closeTab {
  opacity: 1;
}
.tab:hover .thumbnail {
  display: block;
}
.tab:not(.active):hover {
  background: linear-gradient(to bottom, #DFDFDF, #AFB0B4);
}
.tab:not(.active):hover.private {
  background: #665296;
}
.tab.dragging:hover .closeTab {
  opacity: 0;
}
.tab .closeTab {
  opacity: 0;
  margin: auto 0;
  position: absolute;
  right: 0px;
  text-align: center;
  top: 2px;
  width: 24px;
  border: 0px solid white;
  border-radius: 50%;
  z-index: 3;
}
.tab .closeTab:hover {
  opacity: 1;
}
.tabArea {
  box-sizing: border-box;
  display: inline-block;
  padding: 0 2px 0 0;
  position: relative;
  vertical-align: top;
}
.tabArea:not(.partOfFullPageSet) {
  max-width: 184px;
}
.tabArea:not(.isPinned) {
  flex: 1;
}
.tabArea hr.dragIndicator {
  position: absolute;
  top: 0;
  left: -1px;
  z-index: 100;
  height: 100%;
  width: 1px;
  display: none;
}
.tabArea hr.dragIndicator.dragIndicatorEnd {
  bottom: -5px;
  top: 0;
  right: -3px;
  left: unset;
}
.tabArea hr.dragIndicator.dragActive {
  display: block;
  color: #0076FF;
}
.tabsToolbar {
  background: #CCCCCC;
  display: flex;
  height: 26px;
}
.tabsToolbarButtons {
  background: #CCCCCC;
  padding-right: 5px;
}
.tabsToolbarButtons .browserButton {
  display: inline-block;
  line-height: initial;
}
.tabPages {
  background: #CCCCCC;
  border-top: 1px solid gray;
  display: flex;
  height: 14px;
  justify-content: center;
  position: relative;
  text-align: center;
  z-index: 12;
}
.tabPage {
  align-items: center;
  background-color: #7E7F83;
  border-radius: 9px;
  box-sizing: border-box;
  display: inline-block;
  margin: auto 2.5px;
  height: 6px;
  width: 34px;
  vertical-align: middle;
}
.tabPage:hover {
  background-color: #98999c;
}
.tabPage.audioPlaybackActive {
  border: 1px solid #0076FF;
}
.tabPage.active {
  background-color: #eeeeee;
}
.prevTab,
.nextTab {
  color: #3B3B3B;
  font-size: 24px !important;
  height: 20px;
  line-height: 20px !important;
  opacity: 0.5;
  vertical-align: top;
  width: 50px;
}
.prevTab:not([disabled]),
.nextTab:not([disabled]) {
  background: #eeeeee;
  opacity: 1;
}
.prevTab:not([disabled]):hover,
.nextTab:not([disabled]):hover {
  background: #ffffff;
}
.prevTab {
  background: linear-gradient(to right, #7E7F83, #CCCCCC);
  border-bottom-left-radius: 9px;
  border-top-left-radius: 9px;
  padding-left: 10px;
  text-align: left;
  transform: translateX(10px);
}
.nextTab {
  background: linear-gradient(to left, #afb0b4, #cccccc);
  border-bottom-right-radius: 9px;
  border-top-right-radius: 9px;
  float: right;
  padding-right: 10px;
  text-align: right;
  transform: translateX(-20px);
}
.pinnedTabs {
  margin-left: 9px;
}
