/**
 * Navigation layers
 */
/* This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this file,
 * You can obtain one at http://mozilla.org/MPL/2.0/. */
#navigator {
  font-size: 20px;
  height: 34px;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 135px 4px 145px;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  display: flex;
  flex-direction: row;
  -webkit-user-select: none;
  /* Disable selection of button text */
}
#navigator.titleMode input {
  background: #A0A2A4;
  color: white;
  text-align: center;
  font-size: 15px;
  /*
      &:focus {
        -webkit-user-select: none;
        background: @chromePrimary;
        color: white;
      }
      */
}
#navigator.titleMode .startButtons,
#navigator.titleMode .endButtons {
  visibility: hidden;
}
#navigator .loadTime {
  color: #0076FF;
  font-size: 12px;
  position: absolute;
  right: 10px;
  text-align: right;
  top: 7px;
}
#navigator > span {
  -webkit-user-select: none;
}
#navigator > * {
  -moz-window-dragging: no-drag;
}
#navigator form {
  flex: 1;
  position: relative;
}
#navigator input {
  background: #919295;
  border: none;
  border-radius: 13px;
  box-sizing: border-box;
  color: #fff;
  font-size: 13px;
  font-weight: normal;
  height: 24px;
  margin: 0 0 0 1px;
  padding: 0 70px 0 25px;
  text-overflow: ellipsis;
  width: 100%;
}
#navigator input:hover {
  background: #7E7F83;
}
#navigator input:focus {
  background: #fff;
  border: 1px solid #0076FF;
  box-shadow: 0 0 4px #0076FF, inset 0 0 4px #0076FF;
  color: #333333;
  outline: none;
}
#navigator input.private {
  background: #392e54;
  color: #fff;
}
#navigator span.navbutton.remove-bookmark-button {
  color: yellow;
}
#navigator:not(.bookmarked) .remove-bookmark-button,
#navigator.bookmarked .bookmark-button,
#navigator:not(.loading) .stop-button,
#navigator.loading .reload-button {
  display: none;
}
#navigator .urlbarIcon {
  color: #555;
  position: absolute;
  top: 6px;
  left: 9px;
  font-size: 15px;
  min-height: 16px;
  min-width: 16px;
}
#navigator .urlbarIcon.extendedValidation {
  color: green;
}
#navigator ul.urlBarSuggestions {
  background-color: #eeeeee;
  border-radius: 9px;
  box-shadow: 2px 2px 8px #3b3b3b;
  color: #000;
  font-size: 13px;
  padding: 10px 30px;
  position: absolute;
  text-align: left;
  top: 48px;
  box-sizing: border-box;
  width: 100%;
  z-index: 311;
}
#navigator ul.urlBarSuggestions .suggestionIcon {
  margin-right: 10px;
}
#navigator ul.urlBarSuggestions .suggestionText {
  display: inline-block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  width: calc(100% - 30px);
  vertical-align: middle;
}
#navigator ul.urlBarSuggestions li {
  list-style-type: none;
  padding: 10px 0;
  z-index: 333;
}
#navigator ul.urlBarSuggestions li.selected {
  color: #0076FF;
}
#navigator ul.urlBarSuggestions li * {
  /* To allow for mouse listeners to work on the list items. */
  pointer-events: none;
}
#navigator ul.urlBarSuggestions li + li {
  border-top: 1px solid #bbb;
}
.flyoutDialog {
  background-color: #eeeeee;
  border-radius: 9px;
  box-shadow: 2px 2px 8px #3b3b3b;
  color: #000;
  font-size: 13px;
  padding: 10px 30px;
  position: absolute;
  text-align: left;
  top: 48px;
}
.releaseNotes {
  background-color: #eeeeee;
  border-radius: 9px;
  box-shadow: 2px 2px 8px #3b3b3b;
  color: #000;
  font-size: 13px;
  padding: 10px 30px;
  position: absolute;
  top: 48px;
  width: auto;
  margin-left: -250px;
  max-width: 350px;
  text-align: left;
}
.releaseNotes h1 {
  margin-bottom: 10px;
}
.siteInfo > ul {
  background-color: #eeeeee;
  border-radius: 9px;
  box-shadow: 2px 2px 8px #3b3b3b;
  color: #000;
  font-size: 13px;
  padding: 10px 30px;
  position: absolute;
  top: 48px;
  margin-left: -250px;
  text-align: left;
  width: auto;
}
.siteInfo > ul li {
  list-style-type: none;
  padding: 10px 0;
}
.siteInfo > ul li .fa {
  padding-right: 10px;
}
.siteInfo > ul li.extendedValidation {
  color: green;
}
.siteInfo > ul li ul {
  font-size: smaller;
  max-height: 300px;
  overflow-y: scroll;
  margin-top: -20px;
  padding: 0 10px;
  max-width: 350px;
}
.topLevelEndButtons .braveMenu {
  background-image: -webkit-image-set(url(../app/img/braveBtn.png) 1x, url(../app/img/braveBtn2x.png) 2x, url(../app/img/braveBtn3x.png) 3x);
  width: 23px;
  height: 27px;
  margin-top: 1px;
  margin-right: 9px;
}
